// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _test(address target, uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        uint beforeBal = target.balance;
        try c.sendMoney(target, value, "") {} catch { return; }
        assertTrue(target.balance == beforeBal + value);
    }

    function testFuzz_test(address target, uint256 value) public {
        _test(target, value);
    }

    receive() external payable {}
}
